import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { RealJarvisRuntimeAdapter } from "../realClient";
import type { FoundrySnapshot } from "../snapshotTypes";

/**
 * Backend-shaped discovery section generated by
 * tests/foundry/test_command_center_discovery.py assertions — mirrored here
 * as the adapter contract. The e2e harness additionally generates a real
 * fixture from live backend output (scripts/v3_operational_e2e.py).
 */
function baseSnapshot(): FoundrySnapshot {
  return {
    generated_at: "2026-08-22T12:00:00Z",
    source_of_truth: { kind: "append_only_event_ledger", ledger_head_sequence: 1, event_count: 1 },
    supervisor: {},
    system_state: {},
    stop: { active: false, record: null, source: "sentinel_or_durable_control" },
    controls: { goals: [], constraints: [], vetoes: [], reprioritizations: [], redirects: [], paused: false, resume_available: false },
    missions: [],
    workers: [],
    evidence: [],
    verification: [],
    health: { supervisor_status: "RUNNING", trust_state: "LAB", degraded: false },
    systems: [],
    memory: [],
    procedures: [],
    mission_steps: [],
    timeline: [],
    release_identity: {},
    costs: {},
    executive: {
      activation_epoch: null,
      admission_authority: "UNKNOWN",
      latest_decision: null,
      recent_decisions: [],
      calibrations: [],
    },
  };
}

const fullBackendDiscovery = {
  schema: 1,
  state: "FRESH",
  flag_state: "OFF",
  policy_version: "v3-policy-2026-08-21",
  latest_cycle: {
    loop_id: "L-1",
    started_at: "2026-08-22T10:00:00Z",
    completed_at: "2026-08-22T10:01:00Z",
    outcome: "COMPILED",
    decision_id: "dec-L-1",
    mission_id: "M-1",
    candidate_id: "cand-1",
    observed: 3,
    candidates_created: 2,
    scored: 2,
    eligible: 1,
    rejected: 1,
    degraded_sources: [],
    reason: null,
    wait_kind: null,
  },
  cycles: [
    {
      loop_id: "L-1", started_at: "2026-08-22T10:00:00Z", completed_at: "2026-08-22T10:01:00Z",
      outcome: "COMPILED", decision_id: "dec-L-1", mission_id: "M-1", candidate_id: "cand-1",
      observed: 3, candidates_created: 2, scored: 2, eligible: 1, rejected: 1,
      degraded_sources: [], reason: null, wait_kind: null,
    },
  ],
  candidates_recent: [
    {
      candidate_id: "cand-1", fingerprint: "fp-1", type: "repair",
      objective: "Fix support semantics", expected_outcome: "claims marked UNSUPPORTED",
      status: "EXECUTED", created_from: "research:cand-1", updated_at: "2026-08-22T10:00:00Z",
      expires_at: null, evidence_ref_count: 2,
      score: {
        total: 0.58, policy_version: "v3-policy-2026-08-21",
        dimensions: { strategic_fit: 0.8, expected_value: 0.5 },
        calibration_adjust: 0.0, thresholds: { min_total_score: 0.4 },
      },
      rejection: null, superseded_by: null, deferred_until: null,
      mission_id: "M-1", partial: false,
    },
  ],
  selected: {
    decision_id: "dec-L-1", candidate_id: "cand-1", total_score: 0.61,
    comparative_rationale: null, reason: "selected cand-1 over 1 alternatives",
    rejected_alternatives: [{ candidate_id: "cand-2", total_score: 0.44, reason: "ranked below selected" }],
    deferred_alternatives: [{ candidate_id: "cand-3", reason: "stale_historical" }],
    mission_id: "M-1", block_reason: null,
  },
  portfolio_summary: { eligible: 1, deferred: 0, rejected: 1 },
  active_team: [
    { run_id: "run-b1", role: "builder", provider: "prov-x", model: "model-x", status: "COMPLETED", mission_id: "M-1" },
  ],
  verifier: {
    mission_id: "M-1", verdict: "PASS", fresh_session: true,
    independence: "REDUCED", provider: "prov-y",
    builder_run_id: "run-b1", verifier_run_id: "run-v1",
    repair_rounds_used: 0, repair_budget: 3,
  },
  outcomes: [
    {
      candidate_id: "cand-1", mission_id: "M-1", window: "immediate",
      predicted: { expected_success: "0.64" }, actual: null,
      status: "UNKNOWN", confidence: 0.9, delta: null,
    },
  ],
  maintenance_due: null,
  next_action: "RUN_NEXT_CYCLE",
};

describe("RealJarvisRuntimeAdapter.getDiscovery", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn(async () =>
      new Response(JSON.stringify(baseSnapshot()), { status: 200, headers: { "Content-Type": "application/json" } }),
    ));
  });
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("maps a present backend discovery section to the typed view without fixtures", async () => {
    const snapshot = baseSnapshot();
    (snapshot as unknown as Record<string, unknown>).discovery = fullBackendDiscovery;
    vi.stubGlobal("fetch", vi.fn(async () =>
      new Response(JSON.stringify(snapshot), { status: 200, headers: { "Content-Type": "application/json" } }),
    ));
    const client = new RealJarvisRuntimeAdapter({ apiBase: "/api", pollMs: 60000 });
    const view = await client.getDiscovery();
    expect(view.available).toBe(true);
    if (!view.available) throw new Error("unreachable");
    expect(view.flag).toEqual({ key: "discovery.cycle_enabled", enabled: false });
    expect(view.policyVersion).toBe("v3-policy-2026-08-21");
    expect(view.candidatesRecent).toHaveLength(1);
    expect(view.candidatesRecent[0]).toMatchObject({
      id: "cand-1",
      fingerprint: "fp-1",
      type: "repair",
      objective: "Fix support semantics",
      expectedOutcome: "claims marked UNSUPPORTED",
      status: "EXECUTED",
      score: expect.objectContaining({ total: 0.58, policyVersion: "v3-policy-2026-08-21" }),
      rejection: null,
      supersededBy: null,
      deferredUntil: null,
      evidenceRefCount: 2,
      missionId: "M-1",
    });
    expect(view.selected).toMatchObject({
      decisionId: "dec-L-1",
      candidateId: "cand-1",
      totalScore: 0.61,
      missionId: "M-1",
      rejectedAlternatives: [expect.objectContaining({ candidateId: "cand-2", totalScore: 0.44 })],
      deferredAlternatives: [expect.objectContaining({ candidateId: "cand-3" })],
      comparativeRationale: null,
    });
    expect(view.portfolioSummary).toEqual({ eligible: 1, deferred: 0, rejected: 1 });
    expect(view.cycles[0]).toMatchObject({
      loopId: "L-1", outcome: "COMPILED", observed: 3, candidatesCreated: 2,
      scored: 2, eligible: 1, rejected: 1, waitKind: null, nextAction: null,
    });
    expect(view.activeTeam).toHaveLength(1);
    expect(view.verifierState).toMatchObject({
      missionId: "M-1", verdict: "PASS", freshSession: true, independence: "REDUCED",
      repairRoundsUsed: 0, repairBudget: 3,
    });
    expect(view.outcomeMeasurements).toHaveLength(1);
    expect(view.outcomeMeasurements[0]).toMatchObject({
      candidateId: "cand-1", window: "immediate", predicted: { expected_success: "0.64" },
      actual: null, status: "UNKNOWN", delta: null,
    });
    expect(view.maintenanceDue).toBeNull();
    expect(view.nextAction).toBe("RUN_NEXT_CYCLE");
  });

  it("stays honest-unavailable when the backend ships no discovery section", async () => {
    const client = new RealJarvisRuntimeAdapter({ apiBase: "/api", pollMs: 60000 });
    const view = await client.getDiscovery();
    expect(view).toEqual({ available: false, reason: "PROJECTION_NOT_AVAILABLE" });
  });

  it("degrades safely on partial sections with unknown enum values", async () => {
    const snapshot = baseSnapshot();
    (snapshot as unknown as Record<string, unknown>).discovery = {
      ...fullBackendDiscovery,
      state: "PARTIAL",
      flag_state: "SOME_FUTURE_VALUE",
      latest_cycle: { ...fullBackendDiscovery.latest_cycle, outcome: "SOME_NEW_OUTCOME" },
      cycles: [
        { ...fullBackendDiscovery.cycles[0], outcome: "SOME_NEW_OUTCOME" },
      ],
      candidates_recent: [{
        ...fullBackendDiscovery.candidates_recent[0],
        status: "MEASURING",
        score: { total: 0.5, dimensions: {}, thresholds: null, calibrationAdjust: 0, policyVersion: "p" },
      }],
      verifier: null,
      selected: null,
    };
    vi.stubGlobal("fetch", vi.fn(async () =>
      new Response(JSON.stringify(snapshot), { status: 200, headers: { "Content-Type": "application/json" } }),
    ));
    const client = new RealJarvisRuntimeAdapter({ apiBase: "/api", pollMs: 60000 });
    const view = await client.getDiscovery();
    expect(view.available).toBe(true);
    if (!view.available) throw new Error("unreachable");
    // Unknown additive values must not crash or fabricate booleans.
    expect(view.cycles[0].outcome).toBe("SOME_NEW_OUTCOME");
    expect(view.flag.enabled).toBe(false); // non-boolean truth degrades to explicit false
    expect(view.verifierState).toBeNull();
    expect(view.selected).toBeNull();
  });
});
